CREATE TABLE IF NOT EXISTS `fms_subject` (
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `creator` varchar(64) NULL DEFAULT '' COMMENT '创建者，目前使用 SysUser 的 id 编号',
  `updater` varchar(64) NULL DEFAULT '' COMMENT '更新者，目前使用 SysUser 的 id 编号',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `code` varchar(64) NULL DEFAULT NULL COMMENT '科目编码',
  `name` varchar(255) NULL DEFAULT NULL COMMENT '科目名称',
  `parent_id` bigint NULL DEFAULT 0 COMMENT '上级科目编号',
  `type` int NULL DEFAULT NULL COMMENT '科目类型',
  `category` int NULL DEFAULT NULL COMMENT '科目类别',
  `balance_direction` int NULL DEFAULT NULL COMMENT '余额方向',
  `quantity_unit` varchar(255) NULL DEFAULT NULL COMMENT '数量核算 计量单位',
  `cash` bit(1) NULL DEFAULT b'0' COMMENT '是否现金科目',
  `status` int NULL DEFAULT 0 COMMENT '状态',
  `level` int NULL DEFAULT NULL COMMENT '科目层级',
  `quantity_accounting` bit(1) NULL DEFAULT b'0' COMMENT '是否启用数量核算',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `auxiliary_type_ids` json NULL COMMENT '辅助核算类别编号数组',
  `currency_ids` json NULL COMMENT '核算币种编号数组',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号（租户拦截器写入）',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_deleted` (`tenant_id`, `deleted`),
  KEY `idx_parent_id` (`tenant_id`, `parent_id`),
  KEY `idx_account_set_id` (`tenant_id`, `account_set_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='FMS 会计科目 DO';

