-- Entity: yudao-module-fms/src/main/java/cn/iocoder/yudao/module/fms/dal/dataobject/voucher/FmsVoucherDO.java
-- Schema hints: yudao-module-fms/src/test/resources/sql/create_tables.sql
CREATE TABLE IF NOT EXISTS `fms_voucher` (
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `creator` varchar(64) NULL DEFAULT '' COMMENT '创建者，目前使用 SysUser 的 id 编号',
  `updater` varchar(64) NULL DEFAULT '' COMMENT '更新者，目前使用 SysUser 的 id 编号',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `voucher_word_id` bigint NULL DEFAULT NULL COMMENT '凭证字编号',
  `voucher_number` int NULL DEFAULT NULL COMMENT '凭证号',
  `voucher_time` datetime(6) NULL DEFAULT NULL COMMENT '凭证日期',
  `attachment_urls` json NULL COMMENT '附件地址',
  `attachment_count` int NULL DEFAULT 0 COMMENT '附单据张数',
  `debit_amount` decimal(18,2) NULL DEFAULT 0 COMMENT '借方金额',
  `credit_amount` decimal(18,2) NULL DEFAULT 0 COMMENT '贷方金额',
  `total` decimal(18,2) NULL DEFAULT 0.00 COMMENT '合计金额',
  `status` int NULL DEFAULT NULL COMMENT '状态',
  `reviewer_user_id` bigint NULL DEFAULT NULL COMMENT '审核人后台用户编号',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号（租户拦截器写入）',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_deleted` (`tenant_id`, `deleted`),
  KEY `idx_voucher_word_id` (`tenant_id`, `voucher_word_id`),
  KEY `idx_reviewer_user_id` (`tenant_id`, `reviewer_user_id`),
  KEY `idx_account_set_id` (`tenant_id`, `account_set_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='FMS 凭证 DO';

