-- Schema hints: yudao-module-fms/src/test/resources/sql/create_tables.sql
CREATE TABLE IF NOT EXISTS `fms_voucher_entry` (
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `creator` varchar(64) NULL DEFAULT '' COMMENT '创建者，目前使用 SysUser 的 id 编号',
  `updater` varchar(64) NULL DEFAULT '' COMMENT '更新者，目前使用 SysUser 的 id 编号',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `digest` varchar(500) NULL DEFAULT NULL COMMENT '摘要内容',
  `subject_name` varchar(255) NULL DEFAULT NULL COMMENT '科目名称快照',
  `quantity` decimal(18,4) NULL DEFAULT 0 COMMENT '数量',
  `debit_amount` decimal(18,2) NULL DEFAULT 0 COMMENT '借方金额',
  `credit_amount` decimal(18,2) NULL DEFAULT 0 COMMENT '贷方金额',
  `voucher_id` bigint NULL DEFAULT NULL COMMENT '凭证编号',
  `subject_code` varchar(64) NULL DEFAULT NULL COMMENT '科目编码快照',
  `sort` int NULL DEFAULT NULL COMMENT '显示顺序',
  `subject_id` bigint NULL DEFAULT NULL COMMENT '科目编号',
  `account_set_id` bigint NULL DEFAULT NULL COMMENT '账套编号',
  `unit_price` decimal(18,6) NULL DEFAULT 0 COMMENT '单价',
  `assist_combination_id` bigint NULL DEFAULT NULL COMMENT '辅助核算组合编号',
  `auxiliaries` json NULL COMMENT '辅助核算项目数组',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号（租户拦截器写入）',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_deleted` (`tenant_id`, `deleted`),
  KEY `idx_voucher_id` (`tenant_id`, `voucher_id`),
  KEY `idx_subject_id` (`tenant_id`, `subject_id`),
  KEY `idx_account_set_id` (`tenant_id`, `account_set_id`),
  KEY `idx_assist_combination_id` (`tenant_id`, `assist_combination_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='FMS 凭证分录 DO';

